  const lectureKey = Object.keys(CALLS).find((k) => k.startsWith("lecture[") && CALLS[k].lecture?.course === "수문학" && CALLS[k].lecture?.segments?.some(s => s.text.includes("합리식은")));
  const LECTURE = lectureKey ? CALLS[lectureKey].lecture : null;
