  NOTES.forEach((n) => { if (n.exists && !n.url) n.url = "demo:note"; });  // recorded without the local media server
  const SEGMENTS = (LECTURE && LECTURE.segments || []).map((s) => ({ ms: s.start_ms, text: s.text }));
